CREATE VIEW analytics.stg_stock_prices AS
 WITH source AS (
         SELECT raw_stock_prices.ticker,
            raw_stock_prices.price_date,
            raw_stock_prices.open_price,
            raw_stock_prices.high_price,
            raw_stock_prices.low_price,
            raw_stock_prices.close_price,
            raw_stock_prices.adjusted_close,
            raw_stock_prices.volume,
            raw_stock_prices.source,
            raw_stock_prices.ingested_at
           FROM raw.raw_stock_prices
        ), cleaned AS (
         SELECT source.ticker,
            source.price_date,
            source.open_price,
            source.high_price,
            source.low_price,
            source.close_price,
            source.adjusted_close,
            source.volume,
            source.source,
            source.ingested_at,
            CURRENT_TIMESTAMP AS transformed_at
           FROM source
        )
 SELECT ticker,
    price_date,
    open_price,
    high_price,
    low_price,
    close_price,
    adjusted_close,
    volume,
    source,
    ingested_at,
    transformed_at
   FROM cleaned;


